const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = (v, digits=4) => v === null || v === undefined ? '—' : Number(v).toLocaleString('zh-CN',{maximumFractionDigits:digits});
const date = v => v ? new Date(v).toLocaleString('zh-CN',{hour12:false}) : '等待首次同步';
let state, page=1, total=0, searching=false, searchPage=1, searchQuery='', settingsLoaded=false, refreshing=false;
const snapshotCache = new Map();
const snapshotIntervalMs = 10000;
const unselectedSnapshotIntervalMs = 10000;
const selectedSnapshotIntervalMs = 5000;
let selectedAccountId = null;
let selectedLeaderId=null, workspaceTab='accounts', leaderDetailTab='positions', selectedLeaderPage=1, leaderDetailRequest=0;
function nonzeroDecimal(value){if(typeof value!=='string'||!/^[-+]?\d+(?:\.\d+)?$/.test(value))throw new Error('账户数据格式异常');return /[1-9]/.test(value)}
async function loadAccountSnapshot(id,force=false){
 const key=String(id), now=Date.now(), old=snapshotCache.get(key);
 if(old?.promise)return old.promise;
 if(!force&&old&&now-old.attempt<snapshotIntervalMs)return old.data;
 const entry={...old,attempt:now,error:null};
 entry.promise=(async()=>{try{const d=await api('/api/futures-snapshot?'+new URLSearchParams({account_id:key}));
 if(!Array.isArray(d.balances)||!Array.isArray(d.positions))throw new Error('账户数据格式异常');
 const usdt=d.balances.find(x=>x.asset==='USDT');
 if(usdt){nonzeroDecimal(usdt.availableBalance);nonzeroDecimal(usdt.balance)}
 const count=d.positions.filter(x=>nonzeroDecimal(x.positionAmt)).length;
 entry.data={...d,usdt,count};entry.error=null;return entry.data;
 }catch(e){entry.error=e.message;throw e}finally{entry.promise=null;snapshotCache.set(key,entry)}})();
 snapshotCache.set(key,entry);return entry.promise;
}
let snapshotQueue=[],snapshotScheduled=false,refreshSoonTimer=null;
function refreshSoon(){clearTimeout(refreshSoonTimer);refreshSoonTimer=setTimeout(()=>refresh(),80)}
function scheduleSnapshots(){if(document.hidden||!state)return;for(const a of state.futures_accounts){const entry=snapshotCache.get(String(a.id)),interval=a.id===selectedAccountId?selectedSnapshotIntervalMs:unselectedSnapshotIntervalMs;if(entry?.promise||(entry&&Date.now()-entry.attempt<interval))continue;if(snapshotQueue.includes(a.id))continue;snapshotQueue.push(a.id)}if(snapshotQueue.length&&!snapshotScheduled){snapshotScheduled=true;setTimeout(runSnapshotQueue,0)}}
async function runSnapshotQueue(){snapshotScheduled=false;const pending=snapshotQueue;snapshotQueue=[];let changed=false;for(const id of pending){try{await loadAccountSnapshot(id,true);changed=true}catch{changed=true}}if(changed&&!document.hidden)refreshSoon()}
function decimalParts(value){if(value==null)return null;const match=String(value).match(/^([+-]?)(\d+)(?:\.(\d+))?$/);if(!match)return null;const fraction=match[3]||'';return {n:BigInt((match[1]==='-'?'-':'')+match[2]+fraction),d:10n**BigInt(fraction.length)}}
function formatMoney(value){const n=decimalParts(value);if(!n)return '—';const negative=n.n<0n,numerator=(negative?-n.n:n.n)*100n;let units=numerator/n.d;if((numerator%n.d)*2n>=n.d)units++;const whole=String(units/100n).replace(/\B(?=(\d{3})+(?!\d))/g,','),fraction=units%100n;return (negative&&units>0n?'-':'')+whole+(fraction?'.'+String(fraction).padStart(2,'0'):'')}
function formatPrice(value){const text=trimQuantity(value);if(text==='—'||!/^-?\d+(?:\.\d+)?$/.test(text))return text;const negative=text.startsWith('-'),digits=text.replace('-','');const parts=digits.split('.'),whole=parts[0].replace(/\B(?=(\d{3})+(?!\d))/g,','),fraction=parts[1]||'';return (negative&&/[1-9]/.test(whole+fraction)?'-':'')+whole+(fraction?'.'+fraction:'')}
function totalUnrealized(positions){let n=0n,d=1n;for(const p of positions){const x=decimalParts(p.unRealizedProfit);if(!x)return null;const scale=d>x.d?d:x.d;n=n*(scale/d)+x.n*(scale/x.d);d=scale}const negative=n<0n;if(negative)n=-n;const digits=String(n).padStart(String(d).length,'0'),places=String(d).length-1;return (negative?'-':'')+(places?digits.slice(0,-places)+'.'+digits.slice(-places):digits)}
function positionRatio(position){const pnl=decimalParts(position.unRealizedProfit),margin=decimalParts(position.positionInitialMargin);if(!pnl||!margin||margin.n<=0n)return '—';const negative=pnl.n<0n,numerator=(negative?-pnl.n:pnl.n)*margin.d*10000n,denominator=pnl.d*margin.n;let cents=numerator/denominator;if((numerator%denominator)*2n>=denominator)cents++;return (negative&&cents>0n?'-':'')+(cents/100n)+'.'+String(cents%100n).padStart(2,'0')+'%'}
function marginRatio(positions){const pct=positions.map(p=>{const maint=decimalParts(p.maintMargin),margin=decimalParts(p.isolatedMargin);const pnl=decimalParts(p.unRealizedProfit),init=decimalParts(p.positionInitialMargin);const used=margin&&margin.d>0n?margin:(init&&pnl?{n:init.n+pnl.n,d:init.d}:null);if(!maint||!used||used.n<=0n)return null;return Number((maint.n*1000000n/used.n))/10000});const values=pct.filter(v=>v!==null);if(!values.length)return null;return values.reduce((a,b)=>a>b?a:b,0)}
function renderSelectedAccount(){const account=state.futures_accounts.find(a=>a.id===selectedAccountId);const status=$('#positions-status'),body=$('#positions-body');$('#refresh-positions').disabled=!account;if(!account){$('#positions-title').textContent='持仓详情';$('#positions-subtitle').textContent='选择账户查看持仓';status.textContent='暂无账户，请添加合约 API 账号';body.innerHTML='';return}$('#positions-title').textContent=account.name+' · 持仓';$('#positions-subtitle').textContent='选中账户每 5 秒刷新 · 其他账户每 10 秒刷新 · 标记价格';const entry=snapshotCache.get(String(account.id));if(!entry?.data){status.textContent=entry?.error?'查询失败：'+entry.error:'正在加载账户数据…';status.className=entry?.error?'error position-status':'muted position-status';body.innerHTML='';return}const d=entry.data;const positions=d.positions.filter(p=>nonzeroDecimal(p.positionAmt));status.textContent=entry.error?'刷新失败：'+entry.error+' · 以下为上次成功数据（'+date(d.queried_at)+'）':'更新于 '+date(d.queried_at);status.className=entry.error?'error position-status':'muted position-status';body.innerHTML=positions.length?positions.map(p=>{const side=p.positionSide==='BOTH'?(String(p.positionAmt).startsWith('-')?'SHORT':'LONG'):p.positionSide;const pnl=Number(p.unRealizedProfit),cls=Number.isFinite(pnl)?pnl>=0?'positive':'negative':'';return `<tr><td data-label="交易对 / 方向"><span class="pair-side"><strong>${esc(p.symbol)}</strong><span class="tag ${side==='LONG'?'long':'short'}">${side==='LONG'?'多':side==='SHORT'?'空':esc(side)}</span></span></td><td data-label="杠杆">${p.leverage==null?'—':esc(p.leverage)+'×'}</td><td data-label="数量">${positionQuantityTrigger(p.symbol,side,p.positionAmt)}</td><td data-label="开仓均价">${formatPrice(p.entryPrice)}</td><td data-label="标记价格">${formatPrice(p.markPrice)}</td><td data-label="未实现盈亏" class="${cls}">${formatMoney(p.unRealizedProfit)}</td><td data-label="盈亏比例" class="${cls}">${esc(positionRatio(p))}</td><td data-label="持仓初始保证金">${formatMoney(p.positionInitialMargin)}</td><td data-label="强平价格">${formatPrice(p.liquidationPrice)}</td></tr>`}).join(''):'<tr class="positions-empty"><td colspan="9"><div class="empty">当前账户没有持仓</div></td></tr>';refreshAttributionTooltip()}


