async function loadEvents(){if(!recordScope)return;const request=++recordsRequest;const scope={...recordScope},currentPage=page;const params=scope.type==='target'?new URLSearchParams({page:currentPage,target:scope.id,kind:$('#filter-kind').value||'leader',limit:10}):new URLSearchParams({page:currentPage,account_id:scope.id});const data=await api((scope.type==='target'?'/api/events?':'/api/copy-tasks?')+params);if(request!==recordsRequest||!recordScope||recordScope.type!==scope.type||recordScope.id!==scope.id||currentPage!==page)return;total=data.total;const perPage=scope.type==='target'?10:50;$('#events').innerHTML=data.list.length?data.list.map(scope.type==='target'?eventRow:copyTaskRow).join(''):'<tr><td colspan="8"><div class="empty">暂无记录</div></td></tr>';if(scope.type==='account')loadCopyPnl(data.list,scope.id,request);$('#page-info').textContent=`${scope.type==='target'?({'leader':'交易及划转记录','order':'交易记录','transfer':'划转记录'}[params.get('kind')]||'记录'):'跟单记录'}共 ${total} 条 · 第 ${page} / ${Math.max(1,Math.ceil(total/perPage))} 页`;$('#prev').disabled=page<=1;$('#next').disabled=page*perPage>=total}
function directionTag(direction, side){const text=String(direction||'');const action=text.startsWith('开')?'open':text.startsWith('平')?'close':'';const position=side==='LONG'?'long':side==='SHORT'?'short':'';return `<span class="tag trade-direction ${position} ${action}">${esc(text)}</span>`}
function formatDiscovery(ms){return ms===null||ms===undefined?'-':`${(Number(ms)/1000).toFixed(3)} 秒`}
const copyPnlCache=new Map();
async function loadCopyPnl(rows,accountId,request){for(const row of rows){if(request!==recordsRequest||!recordScope||recordScope.type!=='account')return;if(!['close','unmatched_close'].includes(row.action)||!['filled','finished'].includes(row.state)||!(Number(row.result?.executedQty)>0))continue;const cell=document.querySelector(`[data-copy-pnl="${CSS.escape(String(row.id))}"]`);if(!cell)continue;try{const key=String(accountId)+':'+row.id;let pending=copyPnlCache.get(key);if(!pending){pending=api('/api/copy-task-pnl?'+new URLSearchParams({account_id:accountId,task_id:row.id}));copyPnlCache.set(key,pending);pending.catch(()=>copyPnlCache.delete(key))}const data=await pending;if(request!==recordsRequest)return;cell.textContent=data.pnl===null?'—':formatMoney(data.pnl)+' '+data.asset;if(data.pnl!==null)cell.classList.add(Number(data.pnl)<0?'negative':'positive');cell.title='本笔已实现盈亏，不含手续费和资金费';}catch{if(request!==recordsRequest)return;cell.textContent='查询失败';}}}
function copyTaskRow(x){const b=x.body,r=x.result||{},status=({pending:'待执行',submitted:'待确认',filled:'已成交',finished:'已结束',skipped:'已跳过',cancelled:'已取消'})[x.state]||x.state;return `<tr><td>${esc(date(x.created))}<small>${esc(x.target_name||x.target_id)}</small><small>发现延迟 ${formatDiscovery(x.discovery_delay_ms)}</small></td><td><strong>${esc(b.symbol)}</strong><small>${esc(b.positionSide)}</small></td><td>${directionTag(b.direction||({'BUYLONG':'开多','SELLLONG':'平多','SELLSHORT':'开空','BUYSHORT':'平空'})[(b.side||'')+(b.positionSide||'')]||b.side,b.positionSide)}</td><td>${esc(x.planned_quantity??'—')}<small>成交 ${esc(r.executedQty??'—')}</small></td><td>${formatMoney(x.wallet_balance)}<small>${esc(x.asset||'USDT')} 钱包余额 · 可用 ${formatMoney(x.available_balance)}</small></td><td>${esc(status)}<small>${esc(x.error||r.status||'')}</small></td><td data-copy-pnl="${esc(x.id)}">${['close','unmatched_close'].includes(x.action)&&['filled','finished'].includes(x.state)&&Number(r.executedQty)>0?'查询中…':'—'}</td><td>${x.state==='submitted'?`<button type="button" class="row-action" data-resolve-copy="${esc(x.id)}">核对结束</button>`:esc(r.orderId??'—')}</td></tr>`}
function openRecords(type,id,name){recordScope={type,id:String(id)};page=1;$('#records-title').textContent=name+(type==='target'?' · 带单记录':' · 跟单记录');$('#records-subtitle').textContent=type==='target'?'该带单员的交易操作和资金划转':'已实现盈亏按本笔平仓成交统计，不含手续费和资金费';$('#records-tip').textContent=type==='target'?'按类型筛选':'仅显示此账户的跟单任务';$('#filter-kind').hidden=type!=='target';$('#filter-kind').value='';$('#records-head').innerHTML=type==='target'?'<tr><th>时间</th><th>币种 / 类型</th><th>方向</th><th>成交数量</th><th>成交均价</th><th>成交金额</th><th>盈亏 / 账户</th></tr>':'<tr><th>时间 / 带单员</th><th>币种</th><th>方向</th><th>计划 / 成交数量</th><th>下单前资金</th><th>状态</th><th>已实现盈亏</th><th>订单号</th></tr>';$('#events').innerHTML='<tr><td colspan="7" class="muted">加载中…</td></tr>';$('#records-dialog').showModal();loadEvents().catch(e=>toast(e.message))}
function eventRow(e){const b=e.body;const time=`<td>${esc(date(e.stamp))}<small>${esc(e.name)}${e.historical?' · 历史基线':''}</small>${e.kind==='order'?`<small>发现延迟 ${formatDiscovery(e.discovery_delay_ms)}</small>`:''}</td>`;if(e.kind==='copy')return `<tr>${time}<td>跟单结果</td><td colspan="5">${esc(b.message)}</td></tr>`;if(e.kind==='order')return `<tr>${time}<td><strong>${esc(b.symbol)}</strong><small>${esc(b.type)}${b.updated?' · 记录更新':''}</small></td><td>${directionTag(b.direction,b.positionSide)}</td><td>${fmt(b.executedQty,8)}<small>${esc(b.baseAsset)}</small></td><td>${formatPrice(b.avgPrice)}</td><td>${formatMoney(b.notional)}<small>${esc(b.quoteAsset)}</small></td><td class="${Number(b.totalPnl)>=0?'positive':'negative'}">${formatMoney(b.totalPnl)}</td></tr>`;
const label={LEAD_WITHDRAW:'转出',LEAD_DEPOSIT:'转入',LEAD_INVEST:'初始投入'}[b.transType]||b.transType;return `<tr>${time}<td>${esc(b.coin)}<small>资金划转</small></td><td><span class="tag">${esc(label)}</span></td><td>—</td><td>—</td><td>${formatMoney(b.amount)}<small>${esc(b.coin)}</small></td><td>${esc(b.from)}<small>→ ${esc(b.to)}</small></td></tr>`}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/login',{token:$('#token').value});$('#token').value='';$('#login').hidden=true;$('#dashboard').hidden=false;settingsLoaded=false;await refresh()}catch(e){toast(e.message)}});
