setupOrdering('#targets');setupOrdering('#account-list');
$('#targets').addEventListener('click',async e=>{
 const toggle=e.target.closest('[data-leader-toggle]');
 if(toggle){const id=toggle.dataset.leaderToggle;if(leaderTogglePending.has(id))return;leaderTogglePending.add(id);toggle.disabled=true;const enabled=toggle.dataset.enabled==='0';try{await api('/api/toggle',{id,enabled});const target=state.targets.find(t=>String(t.id)===id);if(target)target.enabled=enabled?1:0;toggle.dataset.enabled=enabled?'1':'0';toggle.classList.toggle('on',enabled);toggle.setAttribute('aria-checked',String(enabled));toast(enabled?'监听已开启，正在等待下一次采集':'监听已关闭，自动跟单也已关闭');leaderTogglePending.delete(id);await refresh()}catch(err){toast('保存失败：'+err.message)}finally{leaderTogglePending.delete(id);toggle.disabled=false;const current=document.querySelector(`[data-leader-toggle="${CSS.escape(id)}"]`);if(current)current.disabled=false}return}
 const deletion=e.target.closest('[data-leader-delete]');
 if(deletion){const id=deletion.dataset.leaderDelete,target=state.targets.find(t=>String(t.id)===id);if(!target||leaderDeletePending.has(id)||!await confirmLeaderDelete(target.name))return;leaderDeletePending.add(id);deletion.disabled=true;try{await api('/api/delete-target',{id});leaderDeletePending.delete(id);await refresh();toast('已删除')}catch(err){toast('删除失败：'+err.message)}finally{leaderDeletePending.delete(id);deletion.disabled=false;const current=document.querySelector(`[data-leader-delete="${CSS.escape(id)}"]`);if(current)current.disabled=false}return}
 const selection=e.target.closest('[data-select-leader]');if(!selection)return;selectedLeaderId=String(selection.dataset.selectLeader);selectedLeaderPage=1;resetLeaderDetail();document.querySelectorAll('#targets [data-select-leader]').forEach(el=>{const active=el.dataset.selectLeader===selectedLeaderId;el.classList.toggle('selected',active);el.querySelector('[data-select-leader-button]')?.setAttribute('aria-pressed',String(active))});loadSelectedLeader();
});
$('#config-content').addEventListener('click',async e=>{const save=e.target.closest('[data-save-multiplier]');if(save){const input=save.closest('.config-line').querySelector('[data-multiplier-input]');if(!input.reportValidity())return;save.disabled=true;try{await api('/api/copy-multiplier',{account_id:Number(save.dataset.multiplierAccount),target_id:save.dataset.saveMultiplier,multiplier:input.value});const binding=state.copy_bindings.find(x=>x.account_id===Number(save.dataset.multiplierAccount)&&String(x.target_id)===save.dataset.saveMultiplier);if(binding)binding.multiplier=input.value;toast('倍数已保存，对之后的新跟单生效')}catch(err){toast('保存失败：'+err.message)}finally{save.disabled=false}return}const deletion=e.target.closest('[data-delete-target],[data-delete-account]');if(deletion){const isTarget=!!deletion.dataset.deleteTarget,id=isTarget?deletion.dataset.deleteTarget:Number(deletion.dataset.deleteAccount);if(!confirm('确定删除该'+(isTarget?'带单员':'跟单账户')+'？相关记录和配置将被删除。'))return;deletion.disabled=true;try{await api(isTarget?'/api/delete-target':'/api/delete-account',{id});if(!isTarget)snapshotCache.delete(String(id));$('#config-dialog').close();await refresh();toast('已删除')}catch(err){toast('删除失败：'+err.message)}finally{deletion.disabled=false}return}const edit=e.target.closest('[data-edit-account]');if(edit){const a=state.futures_accounts.find(x=>x.id===Number(edit.dataset.editAccount));if(a){$('#config-dialog').close();openAccountForm(a)}return}const button=e.target.closest('[data-toggle], [data-copy-account]');if(!button)return;button.disabled=true;try{if(button.dataset.toggle){const enabled=button.dataset.enabled==='0',status=$('#monitor-toggle-status');status.className='muted';status.textContent='正在保存…';await api('/api/toggle',{id:button.dataset.toggle,enabled});button.dataset.enabled=enabled?'1':'0';button.classList.toggle('on',enabled);button.setAttribute('aria-checked',String(enabled));const target=state.targets.find(t=>String(t.id)===button.dataset.toggle);if(target)target.enabled=enabled?1:0;const badge=$('#monitor-toggle-label');if(badge){badge.textContent=enabled?'监听中':'已暂停';badge.classList.toggle('active',enabled)}status.textContent=enabled?'监听已开启，正在等待下一次采集':'监听已关闭，自动跟单也已关闭';toast(status.textContent)}else{const enabled=button.dataset.copyActive!=='1';await api('/api/copy-live',{account_id:Number(button.dataset.copyAccount),target_id:button.dataset.copyTarget,enabled});button.dataset.copyActive=enabled?'1':'0';button.classList.toggle('on',enabled);button.setAttribute('aria-checked',String(enabled));const label=button.parentElement.querySelector('.copy-toggle-label');if(label)label.textContent=enabled?'跟单已开启':'跟单已关闭';const badge=button.closest('.copy-leader')?.querySelector('.copy-live-status');if(badge){badge.textContent=enabled?'跟单中':'未开启';badge.classList.toggle('active',enabled)}toast(enabled?'市价自动跟单已开启':'跟单已关闭')}await refresh()}catch(err){const status=$('#monitor-toggle-status');if(status){status.className='error';status.textContent='保存失败：'+err.message}toast('保存失败：'+err.message)}finally{button.disabled=false}});
$('#config-content').addEventListener('change',async e=>{const el=e.target;if(!el.dataset.account)return;el.disabled=true;try{await api('/api/copy-binding',{account_id:Number(el.dataset.account),target_id:el.dataset.target,selected:el.checked});await refresh();renderAccountConfig(Number(el.dataset.account))}catch(err){el.checked=!el.checked;toast(err.message)}finally{el.disabled=false}});
$('#open-search').addEventListener('click',()=>{$('#search-dialog').showModal();$('#query').focus()});$('#close-search').addEventListener('click',()=>$('#search-dialog').close());
async function search(){if(searching)return;searching=true;$('#search-results').innerHTML='<p class="muted">正在搜索…</p>';try{const data=await api('/api/search?'+new URLSearchParams({q:searchQuery,page:searchPage}));$('#search-results').innerHTML=data.list.length?data.list.map(t=>`<article class="result">${image(t.avatarUrl)}<div class="info"><strong>${esc(t.nickname)}</strong><small>30 天盈亏 ${formatMoney(t.pnl)} USDT · ROI ${fmt(t.roi,2)}%</small><small>跟单人数 ${esc(t.currentCopyCount)} / ${esc(t.maxCopyCount)}</small></div><button data-add="${esc(t.leadPortfolioId)}" ${state.targets.some(x=>x.id===t.leadPortfolioId)?'disabled':''}>${state.targets.some(x=>x.id===t.leadPortfolioId)?'已添加':'添加'}</button></article>`).join(''):'<p class="muted">没有找到匹配的带单对象。</p>';$('#search-page').textContent=`第 ${searchPage} 页 · 共 ${data.total} 个`;$('#search-prev').disabled=searchPage===1;$('#search-next').disabled=searchPage*20>=data.total;}catch(e){$('#search-results').textContent=e.message}finally{searching=false}}
$('#search-form').addEventListener('submit',e=>{e.preventDefault();searchQuery=$('#query').value.trim();searchPage=1;search()});$('#search-prev').addEventListener('click',()=>{searchPage--;search()});$('#search-next').addEventListener('click',()=>{searchPage++;search()});
$('#search-results').addEventListener('click',async e=>{const button=e.target.closest('[data-add]');if(!button)return;button.disabled=true;try{await api('/api/targets',{id:button.dataset.add});button.textContent='已添加';toast('已添加，正在同步历史');await refresh()}catch(e){button.disabled=false;toast(e.message)}});
$('#settings-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const data={};for(const el of form.elements){if(el.name)data[el.name]=el.type==='checkbox'?el.checked:el.value}data.page_size=Number(data.page_size);if(data.interval!==undefined)data.interval=Number(data.interval);try{await api('/api/settings',data);form.elements.telegram_token.value='';form.elements.bark_key.value='';form.elements.clear_telegram_token.checked=false;form.elements.clear_bark_key.checked=false;settingsLoaded=false;$('#settings-dialog').close();await refresh();toast('设置已保存')}catch(e){toast(e.message)}});
