setInterval(()=>{if(!$('#dashboard').hidden)scheduleSnapshots()},1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!$('#dashboard').hidden)scheduleSnapshots()});(async()=>{try{await api('/api/state');$('#login').hidden=true;$('#dashboard').hidden=false;await refresh()}catch{$('#dashboard').hidden=true;$('#login').hidden=false}finally{if($('#dashboard').hidden&&$('#login').hidden)$('#login').hidden=false;const boot=$('#boot');if(boot)boot.remove();requestAnimationFrame(()=>document.documentElement.classList.remove('booting'))}})();setInterval(refresh,5000);

document.querySelectorAll('[data-test]').forEach(button=>button.addEventListener('click',async()=>{const form=$('#settings-form'),channel=button.dataset.test;const data={channel};for(const key of (channel==='telegram'?['telegram_token','telegram_chat']:['bark_url','bark_key']))data[key]=form.elements[key].value;button.disabled=true;try{await api('/api/test-notification',data);toast(channel==='bark'&&!state.settings.bark_enabled?'测试消息已发送；请启用 Bark 通知并保存设置':channel==='bark'&&(form.elements.bark_key.value||form.elements.bark_url.value!==state.settings.bark_url)?'测试消息已发送；请保存当前 Bark 配置以用于订单通知':'测试消息发送成功，请查看 '+(channel==='telegram'?'Telegram':'Bark'))}catch(e){toast(e.message)}finally{button.disabled=false}}));

$('#account-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,id=f.dataset.accountId,payload={name:f.elements.name.value,api_key:f.elements.api_key.value,api_secret:f.elements.api_secret.value};if(id)payload.account_id=Number(id);try{await api('/api/futures-account',payload);if(id)snapshotCache.delete(id);f.reset();$('#account-dialog').close();await refresh();toast('账号已保存')}catch(e){toast(e.message)}});
function renderAccountConfig(id){
 const a=state.futures_accounts.find(x=>x.id===id);if(!a)return;
 const breaker=(state.risk_breakers||[]).find(x=>x.scope==='account:'+id);
 const reconAll=(state.position_reconciliation||[]).filter(x=>x.account_id===id);
 const countOf=status=>reconAll.filter(x=>x.status===status).length;
 const reconBlocks=[
  ['over','待处理超配',countOf('over')-reconAll.filter(x=>x.status==='over'&&x.acknowledged).length,'critical'],
  ['ack','已确认超配',reconAll.filter(x=>x.status==='over'&&x.acknowledged).length,'muted'],
  ['unattributed','未归属持仓',countOf('unattributed'),'warn'],
  ['match','一致',countOf('match'),'ok']
 ];
 const order={over:0,unattributed:1,match:2};
 const reconRows=[...reconAll].sort((a,b)=>(order[a.status]??3)-(order[b.status]??3)||String(a.symbol).localeCompare(String(b.symbol))||String(a.position_side).localeCompare(String(b.position_side)));
 const riskSection=breaker?`<section class="copy-config-section"><div class="copy-config-heading"><div><h3>风控暂停</h3><p>${esc(breaker.reason)}</p></div><button type="button" class="secondary" data-reset-breaker="account:${id}">解除暂停</button></div></section>`:'';
 const reconSection=reconAll.length?`<section class="copy-config-section"><div class="copy-config-heading"><div><h3>持仓对账</h3><p>本地归属 vs 交易所实际持仓</p></div><button type="button" class="secondary recon-toggle" data-recon-toggle="${id}">查看明细</button></div><div class="recon-summary">${reconBlocks.map(b=>`<div class="recon-summary-item ${b[3]}"><span class="recon-summary-label">${b[1]}</span><strong class="recon-summary-value">${b[2]}</strong></div>`).join('')}</div><div class="recon-detail" hidden><div class="recon-table"><div class="recon-row recon-head"><span>交易对 / 方向</span><span>状态</span><span>实际持仓</span><span>本地归属</span><span>差异</span></div>${reconRows.map(x=>{const state=x.status==='over'?(x.acknowledged?['超配 · 已确认','muted']:['超配 · 待处理','critical']):x.status==='unattributed'?['未归属','warn']:['一致','ok'];const diff=Number(x.difference);return `<div class="recon-row ${state[1]}"><span class="recon-pair"><strong>${esc(x.symbol)}</strong><em>${esc(x.position_side)}</em></span><span class="recon-badge ${state[1]}">${state[0]}</span><span class="recon-value" data-label="实际持仓">${esc(trimQuantity(x.actual_quantity))}</span><span class="recon-value" data-label="本地归属">${esc(trimQuantity(x.local_quantity))}</span><span class="recon-value recon-diff" data-label="差异">${diff>0?'+':''}${esc(trimQuantity(x.difference))}</span></div>`}).join('')}</div></div></section>`:'';
 $('#config-title').textContent=a.name;$('#config-subtitle').textContent='开仓按资金比例乘以倍数，平仓按持仓比例执行';
 const recent=state.copy_tasks.filter(x=>x.account_id===id).slice(0,5);
 const leaders=state.targets.map(t=>{
  const binding=state.copy_bindings.find(b=>b.account_id===id&&b.target_id===t.id),bound=!!binding,live=state.copy_live.some(b=>b.account_id===id&&b.target_id===t.id&&b.enabled);
  return `<div class="config-line copy-leader ${bound?'is-bound':''}"><div class="copy-leader-top"><label class="config-name"><input type="checkbox" data-account="${id}" data-target="${esc(t.id)}" ${bound?'checked':''}><span><strong>${esc(t.name)}</strong><small>${t.enabled?'监听中':'监听已暂停'}</small></span></label>${bound?`<span class="copy-live-status ${live?'active':''}">${live?'跟单中':'未开启'}</span>`:''}</div>${bound?`<div class="copy-leader-controls"><label class="copy-multiplier">跟单倍数 <input type="number" min="0.0001" max="100" step="0.0001" required value="${esc(binding.multiplier)}" data-multiplier-input aria-label="${esc(t.name)}跟单倍数"><span>倍</span></label><button type="button" class="secondary" data-save-multiplier="${esc(t.id)}" data-multiplier-account="${id}">保存</button><div class="copy-toggle-control"><span class="copy-toggle-label">${live?'跟单已开启':'跟单已关闭'}</span><button type="button" class="switch ${live?'on':''}" role="switch" aria-checked="${!!live}" aria-label="${esc(t.name)}跟单开关" data-copy-account="${id}" data-copy-target="${esc(t.id)}" data-copy-active="${live?'1':'0'}"></button></div></div>`:''}</div>`
 }).join('');
 const history=recent.map(x=>`<div class="copy-recent-row"><div><strong>${esc(JSON.parse(x.body).symbol)}</strong><span>${esc(({pending:'待执行',submitted:'待确认',filled:'已成交',finished:'已结束',skipped:'已跳过',cancelled:'已取消'})[x.state]||x.state)}</span></div>${x.error?`<p class="error">${esc(x.error)}</p>`:''}${x.available_balance!==null&&x.available_balance!==undefined?`<p>下单前钱包 ${formatMoney(x.wallet_balance)} ${esc(x.asset)} · 可用 ${formatMoney(x.available_balance)}<br>带单余额 ${formatMoney(x.lead_balance)} · 数量 ${esc(x.planned_quantity)}</p>`:''}</div>`).join('');
 $('#config-content').innerHTML=`${riskSection}${reconSection}<section class="copy-config-section"><div class="copy-config-heading"><div><h3>带单员设置</h3><p>勾选关联对象，设置倍数并开启跟单</p></div><span>${state.copy_bindings.filter(b=>b.account_id===id).length} 位已关联</span></div><div class="copy-leader-list">${leaders||'<p class="muted">请先添加带单员。</p>'}</div></section>${recent.length?`<details class="copy-recent"><summary>最近跟单 <span>${recent.length} 条</span></summary><div class="copy-recent-list">${history}</div></details>`:''}<div class="copy-account-actions"><button type="button" class="secondary" data-edit-account="${id}">编辑账户</button><button type="button" class="quiet copy-delete" data-delete-account="${id}">删除账户</button></div>`;
}
