function estimatedLeaderPnl(position,mark){const q=decimalParts(position.quantity),entry=decimalParts(position.avg_price),price=decimalParts(mark);if(position.uncertain||!q||!entry||!price||q.n<=0n||entry.n<=0n||price.n<=0n||!['LONG','SHORT'].includes(position.side))return null;const diff=price.n*entry.d-entry.n*price.d, sign=position.side==='LONG'?1n:-1n, numerator=diff*q.n*sign*10000n,denominator=price.d*entry.d*q.d,negative=numerator<0n,absolute=negative?-numerator:numerator;let units=absolute/denominator;if((absolute%denominator)*2n>=denominator)units++;return (negative&&units>0n?'-':'')+String(units/10000n)+'.'+String(units%10000n).padStart(4,'0')}

