document.querySelectorAll('[data-leader-detail]').forEach(button=>button.addEventListener('click',()=>{leaderDetailTab=button.dataset.leaderDetail;selectedLeaderPage=1;document.querySelectorAll('[data-leader-detail]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active))});$('#selected-leader-positions').hidden=leaderDetailTab!=='positions';$('#selected-leader-orders').hidden=leaderDetailTab!=='orders';resetLeaderDetail();loadSelectedLeader()}));
let leaderDetailPending=null;
async function loadSelectedLeader(){
 const target=state?.targets.find(t=>String(t.id)===selectedLeaderId);$('#selected-leader-refresh').disabled=!target;$('#selected-leader-title').textContent=target?target.name+' · 带单详情':'带单员详情';$('#selected-leader-subtitle').textContent=target?'持仓为历史重放估算 · 订单为已保存记录':'选择带单员查看持仓与订单';
 if(!target){leaderDetailRequest++;$('#selected-leader-status').textContent='暂无带单员';$('#selected-leader-positions-body').innerHTML='<tr><td colspan="6" class="muted">暂无可重放持仓</td></tr>';$('#selected-leader-orders-body').innerHTML='<tr><td colspan="7" class="muted">暂无订单记录</td></tr>';$('#selected-leader-page-info').textContent='';$('#selected-leader-prev').disabled=true;$('#selected-leader-next').disabled=true;return}
 const id=selectedLeaderId,tab=leaderDetailTab,currentPage=selectedLeaderPage,key=[id,tab,currentPage].join(':');if(leaderDetailPending?.key===key&&leaderDetailPending.request===leaderDetailRequest)return;const request=++leaderDetailRequest;leaderDetailPending={key,request};const valid=()=>request===leaderDetailRequest&&workspaceTab==='leaders'&&selectedLeaderId===id&&leaderDetailTab===tab&&selectedLeaderPage===currentPage;
 try{
  if(tab==='positions'){
   const d=await api('/api/leader-positions?target='+encodeURIComponent(id));if(!valid())return;
   let prices={};if(d.positions.length){try{const quotes=await api('/api/leader-mark-prices');prices=quotes.prices||{}}catch{}}if(!valid())return;
   const sync=d.sync,missingPrice=d.positions.some(p=>!prices[p.symbol]);let message=d.monitor.error?'实时采集异常：'+d.monitor.error:!d.monitor.enabled?'实时监听已暂停':sync?.complete?'历史同步完成 · 已保存 '+d.count+' 条成交':sync?.error?'历史同步暂停：'+sync.error:d.history_active?'历史正在同步 · 已保存 '+d.staged+' 条成交':'历史未完成 · 已保存 '+d.count+' 条成交';if(missingPrice)message+=' · 部分标记价格暂不可用';
   const rows=d.positions.length?d.positions.map(p=>{const mark=prices[p.symbol],pnl=estimatedLeaderPnl(p,mark),pnlClass=pnl===null?'':pnl.startsWith('-')?'negative':'positive',unit=p.symbol.endsWith('USDT')?'USDT':p.symbol.endsWith('USDC')?'USDC':'';return `<tr><td><strong>${esc(p.symbol)}</strong></td><td><span class="tag ${p.side==='LONG'?'long':'short'}">${p.side==='LONG'?'多':'空'}</span></td><td>${p.quantity==null?'未知':esc(p.quantity)}</td><td>${p.avg_price==null?'未知':formatPrice(p.avg_price)}</td><td>${mark?formatPrice(mark):'—'}</td><td class="${pnlClass}">${pnl===null?'—':formatMoney(pnl)+(unit?' '+unit:'')}</td></tr>`}).join(''):'<tr><td colspan="6" class="muted">暂无可重放持仓</td></tr>';
   $('#selected-leader-positions-body').innerHTML=rows;$('#selected-leader-status').textContent=message;
  }else{
   const params=new URLSearchParams({page:currentPage,target:id,kind:'order',limit:10}),d=await api('/api/events?'+params);if(!valid())return;$('#selected-leader-status').textContent='展示该带单员已保存的交易记录';$('#selected-leader-orders-body').innerHTML=d.list.length?d.list.map(eventRow).join(''):'<tr><td colspan="7" class="muted">暂无订单记录</td></tr>';$('#selected-leader-page-info').textContent=`共 ${d.total} 条 · 第 ${currentPage} / ${Math.max(1,Math.ceil(d.total/10))} 页`;$('#selected-leader-prev').disabled=currentPage<=1;$('#selected-leader-next').disabled=currentPage*10>=d.total;
  }
 }catch(e){if(valid())$('#selected-leader-status').textContent='查询失败：'+e.message}finally{if(leaderDetailPending?.request===request)leaderDetailPending=null}
}
$('#selected-leader-prev').addEventListener('click',()=>{if(selectedLeaderPage>1){selectedLeaderPage--;resetLeaderDetail();loadSelectedLeader()}});
$('#selected-leader-next').addEventListener('click',()=>{selectedLeaderPage++;resetLeaderDetail();loadSelectedLeader()});
$('#selected-leader-refresh').addEventListener('click',async e=>{if(!selectedLeaderId)return;const button=e.currentTarget,id=selectedLeaderId;button.disabled=true;try{await api('/api/leader-history-refresh',{target:id});toast('已开始更新交易历史');if(id===selectedLeaderId){resetLeaderDetail();loadSelectedLeader()}}catch(error){toast(error.message)}finally{button.disabled=!selectedLeaderId}});

let inlineCopyPage=1,inlineCopyRequest=0,inlineCopyPending=null;
async function loadInlineCopyRecords(){
 const account=state?.futures_accounts.find(a=>a.id===selectedAccountId);$('#inline-copy-title').textContent=account?account.name+' · 跟单记录':'跟单记录';
 if(!$('#inline-copy-disclosure').open)return;
 if(!account){inlineCopyRequest++;$('#inline-copy-body').innerHTML='<tr><td colspan="8" class="muted">选择账户查看跟单记录</td></tr>';$('#inline-copy-page-info').textContent='';$('#inline-copy-prev').disabled=true;$('#inline-copy-next').disabled=true;return}
 const accountId=account.id,currentPage=inlineCopyPage,key=accountId+':'+currentPage;if(inlineCopyPending?.key===key&&inlineCopyPending.request===inlineCopyRequest)return;const request=++inlineCopyRequest;inlineCopyPending={key,request};const valid=()=>request===inlineCopyRequest&&workspaceTab==='accounts'&&$('#inline-copy-disclosure').open&&selectedAccountId===accountId&&inlineCopyPage===currentPage;
 try{const data=await api('/api/copy-tasks?'+new URLSearchParams({account_id:accountId,page:currentPage,limit:10}));if(!valid())return;$('#inline-copy-body').innerHTML=data.list.length?data.list.map(copyTaskRow).join(''):'<tr><td colspan="8" class="muted">暂无跟单记录</td></tr>';$('#inline-copy-page-info').textContent=`共 ${data.total} 条 · 第 ${currentPage} / ${Math.max(1,Math.ceil(data.total/10))} 页`;$('#inline-copy-prev').disabled=currentPage<=1;$('#inline-copy-next').disabled=currentPage*10>=data.total;
  for(const row of data.list){if(!valid())return;if(!['close','unmatched_close'].includes(row.action)||!['filled','finished'].includes(row.state)||!(Number(row.result?.executedQty)>0))continue;const cell=$('#inline-copy-body').querySelector(`[data-copy-pnl="${CSS.escape(String(row.id))}"]`);if(!cell)continue;try{const cacheKey=String(accountId)+':'+row.id;let pending=copyPnlCache.get(cacheKey);if(!pending){pending=api('/api/copy-task-pnl?'+new URLSearchParams({account_id:accountId,task_id:row.id}));copyPnlCache.set(cacheKey,pending);pending.catch(()=>copyPnlCache.delete(cacheKey))}const pnl=await pending;if(!valid())return;cell.textContent=pnl.pnl===null?'—':formatMoney(pnl.pnl)+' '+pnl.asset;if(pnl.pnl!==null)cell.classList.add(Number(pnl.pnl)<0?'negative':'positive')}catch{if(valid())cell.textContent='查询失败'}}
 }catch(e){if(valid())$('#inline-copy-body').innerHTML=`<tr><td colspan="8" class="error">查询失败：${esc(e.message)}</td></tr>`}finally{if(inlineCopyPending?.request===request)inlineCopyPending=null}
}
$('#inline-copy-prev').addEventListener('click',()=>{if(inlineCopyPage>1){inlineCopyPage--;inlineCopyRequest++;loadInlineCopyRecords()}});
$('#inline-copy-next').addEventListener('click',()=>{inlineCopyPage++;inlineCopyRequest++;loadInlineCopyRecords()});

$('#inline-copy-disclosure').addEventListener('toggle',()=>{inlineCopyRequest++;if($('#inline-copy-disclosure').open&&workspaceTab==='accounts')loadInlineCopyRecords()});

function positionAttributionData(symbol,side,amount){
 if(!Array.isArray(state.copied_positions))return {error:'跟单归属暂不可用'};
 const candidates=state.copied_positions.filter(x=>x.account_id===selectedAccountId&&x.symbol===symbol&&x.position_side===side);
 if(candidates.some(x=>!decimalParts(x.quantity)))return {error:'跟单记录异常，请核对'};
 const rows=candidates.filter(x=>decimalParts(x.quantity).n!==0n);
 let actual=decimalParts(amount);if(!actual)return {error:'持仓数量不可用'};
 actual.n=actual.n<0n?-actual.n:actual.n;let n=actual.n,d=actual.d;
 for(const x of rows){const q=decimalParts(x.quantity);if(!q||q.n<0n)return {error:'跟单记录异常，请核对'};const scale=d>q.d?d:q.d;n=n*(scale/d)-q.n*(scale/q.d);d=scale}
 const digits=String(n<0n?-n:n).padStart(String(d).length,'0'),places=String(d).length-1;
 return {rows,unmatched:n<0n?null:(places?digits.slice(0,-places)+'.'+digits.slice(-places):digits),mismatch:n<0n};
}
function renderPositionAttribution(symbol,side,amount){
 const data=positionAttributionData(symbol,side,amount);
 if(data.error)return `<span class="position-ownership error">${esc(data.error)}</span>`;
 const rows=data.rows.map(x=>`<span><span>${esc(x.target_name)}</span><b>${esc(trimQuantity(x.quantity))}</b></span>`).join('');
 const extra=data.mismatch?'<span class="error">跟单数量超过实际持仓，请核对</span>':(nonzeroDecimal(data.unmatched)?`<span><span title="可能包含历史缺失的跟单">未关联仓位</span><b>${esc(trimQuantity(data.unmatched))}</b></span>`:'');
 return `<span class="position-ownership" aria-label="持仓归属"><span class="position-ownership-title">当前跟单持仓</span>${rows||(!extra?'<span>暂无跟单记录</span>':'')}${extra}</span>`;
}

let attributionActive=null;
function trimQuantity(value){if(value===null||value===undefined)return '—';const text=String(value).trim();if(!/^[-+]?\d+(?:\.\d+)?$/.test(text))return text;let result=text;if(text.includes('.')){result=text.replace(/0+$/,'').replace(/\.$/,'')}return result==='-0'?'0':result}
function positionQuantityTrigger(symbol,side,amount){
 const data=positionAttributionData(symbol,side,amount),warning=data.mismatch||!!data.error;
 const shown=trimQuantity(amount);return `<button type="button" class="position-quantity-trigger${warning?' has-warning':''}" data-position-symbol="${esc(symbol)}" data-position-side="${esc(side)}" data-position-amount="${esc(amount)}" aria-label="${esc(symbol)} 持仓 ${esc(shown)}，查看跟单归属${warning?'，数量异常':''}" aria-describedby="position-tooltip">${esc(shown)}<span class="quantity-info" aria-hidden="true">${warning?'!':'ⓘ'}</span></button>`;
}
function hideAttributionTooltip(){attributionActive=null;$('#position-tooltip').hidden=true}
function showAttributionTooltip(button){
 const tooltip=$('#position-tooltip');attributionActive={account:selectedAccountId,symbol:button.dataset.positionSymbol,side:button.dataset.positionSide};
 tooltip.innerHTML=renderPositionAttribution(button.dataset.positionSymbol,button.dataset.positionSide,button.dataset.positionAmount);tooltip.hidden=false;
 const rect=button.getBoundingClientRect(),width=tooltip.offsetWidth,height=tooltip.offsetHeight;
 tooltip.style.left=Math.max(8,Math.min(rect.left,window.innerWidth-width-8))+'px';
 tooltip.style.top=Math.max(8,rect.bottom+8+height>window.innerHeight?rect.top-height-8:rect.bottom+8)+'px';
}
function refreshAttributionTooltip(){
 if(!attributionActive)return;
 if(attributionActive.account!==selectedAccountId){hideAttributionTooltip();return}
 const button=Array.from(document.querySelectorAll('[data-position-symbol]')).find(el=>el.dataset.positionSymbol===attributionActive.symbol&&el.dataset.positionSide===attributionActive.side);
 if(button)showAttributionTooltip(button);else hideAttributionTooltip();
}
const positionBody=$('#positions-body');
positionBody.addEventListener('pointerover',e=>{const button=e.target.closest('[data-position-symbol]');if(button&&e.pointerType!=='touch')showAttributionTooltip(button)});
positionBody.addEventListener('pointerout',e=>{const button=e.target.closest('[data-position-symbol]');if(button&&!button.contains(e.relatedTarget)&&e.pointerType!=='touch')hideAttributionTooltip()});
positionBody.addEventListener('focusin',e=>{const button=e.target.closest('[data-position-symbol]');if(button)showAttributionTooltip(button)});
positionBody.addEventListener('focusout',e=>{if(e.target.closest('[data-position-symbol]'))hideAttributionTooltip()});
positionBody.addEventListener('click',e=>{const button=e.target.closest('[data-position-symbol]');if(button)showAttributionTooltip(button)});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('[data-position-symbol]'))hideAttributionTooltip()});
window.addEventListener('resize',refreshAttributionTooltip);
document.addEventListener('click',async e=>{const b=e.target.closest('[data-resolve-copy]');if(!b)return;e.preventDefault();e.stopPropagation();const id=Number(b.dataset.resolveCopy);if(!confirm('会先向交易所查询原订单；只有确认订单不存在时才会结束该任务，不会重发。继续？'))return;b.disabled=true;try{const data=await api('/api/resolve-copy-task',{id});toast(data.result==='settled'?'交易所订单已确认，按成交结果结算':'交易所无此订单，任务已结束');await refresh()}catch(err){toast(err.message)}finally{b.disabled=false}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-reset-breaker]');if(!b)return;e.preventDefault();e.stopPropagation();const scope=b.dataset.resetBreaker;if(!confirm('确认已核对持仓和 API Key，解除该风控暂停？解除后不会自动开启跟单；当前对账差异会记录为已人工确认，之后同一差异不会再自动暂停跟单。'))return;b.disabled=true;try{await api('/api/risk-breaker',{scope,action:'reset'});toast('风控暂停已解除，请核对后自行开启跟单');await refresh()}catch(err){toast(err.message)}finally{b.disabled=false}});

document.addEventListener('click',e=>{const button=e.target.closest('[data-recon-toggle]');if(!button)return;e.preventDefault();e.stopPropagation();const detail=button.closest('.copy-config-section').querySelector('.recon-detail');if(!detail)return;detail.hidden=!detail.hidden;button.setAttribute('aria-expanded',String(!detail.hidden));button.textContent=detail.hidden?'查看明细':'收起明细'});
